program Pets;
{$mode objfpc}{$H+}
type
  TPet = record
    name: string;
    age: integer;
  end;
var
  pet: TPet;
begin
  pet.name := 'Rex';
  pet.age := 3;
  writeln(pet.name, ' is ', pet.age);
  pet.age := pet.age + 1;
  writeln(pet.name, ' is now ', pet.age);
end.

program Points;
{$mode objfpc}{$H+}
type
  TPoint = record
    x, y: integer;
  end;
var
  a, b: TPoint;
  path: array[1..3] of TPoint;
  i: integer;
begin
  a.x := 1;
  a.y := 2;
  b := a;
  b.x := 10;
  writeln(a.x, ' ', b.x);
  for i := 1 to 3 do
  begin
    path[i].x := i;
    path[i].y := i * i;
  end;
  writeln(path[3].x, ',', path[3].y);
end.

program Sizes;
{$mode objfpc}{$H+}
type
  TSize = (Small, Medium, Large);
var
  s: TSize;
begin
  s := Medium;
  writeln(s, ' ', ord(s), ' ', succ(s));
  for s := Small to Large do
    writeln(ord(s), ': ', s);
end.

program Lights;
