end.

program Days;
{$mode objfpc}{$H+}
type
  TDay = (Mon, Tue, Wed, Thu, Fri, Sat, Sun);
  TDays = set of TDay;
var
  free: TDays;
  d: TDay;
begin
  free := [Sat, Sun];
  Include(free, Wed);
  writeln(Wed in free);
  writeln(Mon in free);
  for d := Mon to Sun do
    if d in free then
      writeln(d);
end.

